//		Exec(ctx)
func (_c *PropertyVersionCreate) OnConflictColumns(columns ...string) *PropertyVersionUpsertOne {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &PropertyVersionUpsertOne{
		create: _c,
	}
}

